import re; from .rules import RULES; TOK = re.compile(r"--[^\n]*|/\*.*?\*/|(?<![\w$])[eE]'(?:[^'\\]|\\.|'')*'|'(?:[^']|'')*'|(?<![\w$])\$((?:[A-Za-z_]\w*)?)\$.*?\$\1\$|\x22(?:[^\x22]|\x22\x22)*\x22", re.S); C = [(r[0], r[1], re.compile(r[2], re.I | re.S), r[3]) for r in RULES]; clean = lambda sql: TOK.sub(lambda m: '"' + re.sub(r"[^\n]", "_", m.group(0)[1:-1]) + '"' if m.group(0)[0] == '"' else re.sub(r"[^\n]", " ", m.group(0)), sql); scan = lambda sql: [(sql[:m.start(1)].count("\n") + 1, r[0], r[1], r[3]) for m in re.finditer(r"\s*([^;]+)", clean(sql)) if m.group(1).strip() for r in C if r[2].search(m.group(1))]
